# ==============================================================================
# EyeCam Studio - Windows Laptop Bezel Frame Icon (.ico)
# ==============================================================================
$targetDir = if ($PSScriptRoot) {
    Join-Path $PSScriptRoot "..\..\src\windows\gui"
} else {
    Join-Path (Get-Location).Path "src\windows\gui"
}
$targetDir = [System.IO.Path]::GetFullPath($targetDir)
if (-not (Test-Path $targetDir)) {
    New-Item -ItemType Directory -Path $targetDir -Force | Out-Null
}
$icoPath = Join-Path $targetDir "eyecam_pc.ico"
$b64 = ""
[System.IO.File]::WriteAllBytes($icoPath, [System.Convert]::FromBase64String($b64))
Write-Host "[EyeCam] Successfully generated $icoPath"
exit 0
